6: /// <summary>
7: /// TR-MCP-NUKE-018: Production Linux provisioning of the provider test endpoints (operator decision 2026-10-11,
8: /// BUG-BASELINE-005). Each variable already set is adopted; otherwise it is loaded from the test-database env file and
9: /// its dedicated qbrain-test container is started when stopped. Every endpoint must accept TCP before tests run.
10: /// Actions and errors name variables, the file, containers and host:port only, never connection-string values.
11: /// </summary>
12: sealed class LinuxProviderTestProvisioner : IProviderTestProvisioner
13: {
14:     private static readonly TimeSpan ProbeTimeout = TimeSpan.FromSeconds(2);
15:     private const int ProbeAttempts = 30;
16: 
17:     private static readonly (string Variable, string Container, int DefaultPort, bool IsSqlServer)[] Endpoints =
18:     [
19:         (ProviderTestNames.PostgresVariable, ProviderTestNames.PostgresContainer, 5432, false),
20:         (ProviderTestNames.SqlServerVariable, ProviderTestNames.SqlServerContainer, 1433, true),
21:     ];
22: 
23:     /// <inheritdoc />
24:     public ProviderTestProvisioningResult Provision(string envFilePath, IProviderTestHost host)
25:     {
26:         ArgumentException.ThrowIfNullOrWhiteSpace(envFilePath);
27:         ArgumentNullException.ThrowIfNull(host);
28:         var actions = new List<string>();
29:         var errors = new List<string>();
30:         Dictionary<string, string>? fileValues = null;
31:         var fileMissing = false;
32: 
33:         foreach (var (variable, container, defaultPort, isSqlServer) in Endpoints)
34:         {
35:             var value = host.GetVariable(variable);
36:             var loadedFromFile = false;
37:             if (!string.IsNullOrWhiteSpace(value))
38:             {
39:                 actions.Add("adopt " + variable + " (already set)");
40:             }
41:             else
42:             {
43:                 if (fileValues is null && !fileMissing)
44:                 {
45:                     var text = host.ReadFile(envFilePath);
46:                     if (text is null)
47:                     {
48:                         fileMissing = true;
49:                         errors.Add("test-database env file not found: " + envFilePath);
50:                     }
51:                     else
52:                     {
53:                         fileValues = ParseEnvFile(text);
54:                     }
55:                 }
56: 
57:                 if (fileMissing)
58:                 {
59:                     continue;
60:                 }
61: 
62:                 if (!fileValues!.TryGetValue(variable, out value) || string.IsNullOrWhiteSpace(value))
63:                 {
64:                     errors.Add(variable + " is not defined in " + envFilePath);
65:                     continue;
66:                 }
67: 
68:                 host.SetVariable(variable, value);
69:                 actions.Add("load " + variable + " from " + envFilePath);
70:                 loadedFromFile = true;
71:             }
72: 
73:             var startedNow = false;
74:             if (loadedFromFile)
75:             {
76:                 var state = host.GetContainerState(container);
77:                 if (state == ProviderTestContainerState.Missing)
78:                 {
79:                     errors.Add("container " + container + " not found");
80:                     continue;
81:                 }
82: 
83:                 if (state == ProviderTestContainerState.Stopped)
84:                 {
85:                     if (!host.StartContainer(container))
86:                     {
87:                         errors.Add("container " + container + " could not be started");
88:                         continue;
89:                     }
90: 
91:                     actions.Add("start " + container);
92:                     startedNow = true;
93:                 }
94:             }
95: 
96:             if (!TryReadEndpoint(value, isSqlServer, defaultPort, out var endpointHost, out var port, out var problem))
97:             {
98:                 errors.Add(variable + " " + problem);
99:                 continue;
100:             }
101: 
102:             var endpoint = endpointHost + ":" + port.ToString(CultureInfo.InvariantCulture);
103:             var attempts = startedNow ? ProbeAttempts : 1;
104:             var reachable = false;
105:             for (var attempt = 0; attempt < attempts && !reachable; attempt++)
106:             {
107:                 reachable = host.CanConnect(endpointHost, port, ProbeTimeout);
108:                 if (!reachable && attempt + 1 < attempts)
109:                 {
110:                     Thread.Sleep(TimeSpan.FromSeconds(1));
111:                 }
112:             }
113: 
114:             if (reachable)
115:             {
116:                 actions.Add("endpoint " + endpoint + " reachable");
117:             }
118:             else
119:             {
120:                 errors.Add("endpoint " + endpoint + " for " + variable + " is not accepting connections");
121:             }
122:         }
123: 
124:         return new ProviderTestProvisioningResult(actions, errors);
125:     }
