127:     /// <summary>Parses KEY=VALUE lines; skips blanks and comments; strips an export prefix and matching quotes.</summary>
128:     internal static Dictionary<string, string> ParseEnvFile(string text)
129:     {
130:         var values = new Dictionary<string, string>(StringComparer.Ordinal);
131:         foreach (var raw in text.Split('\n'))
132:         {
133:             var line = raw.Trim();
134:             if (line.Length == 0 || line.StartsWith('#'))
135:             {
136:                 continue;
137:             }
138: 
139:             if (line.StartsWith("export ", StringComparison.Ordinal))
140:             {
141:                 line = line["export ".Length..].TrimStart();
142:             }
143: 
144:             var equals = line.IndexOf('=', StringComparison.Ordinal);
145:             if (equals <= 0)
146:             {
147:                 continue;
148:             }
149: 
150:             var key = line[..equals].Trim();
151:             var value = line[(equals + 1)..].Trim();
152:             if (value.Length >= 2 && (value[0] == '"' || value[0] == '\'') && value[^1] == value[0])
153:             {
154:                 value = value[1..^1];
155:             }
156: 
157:             values[key] = value;
158:         }
159: 
160:         return values;
161:     }
