163:     private static bool TryReadEndpoint(string connectionString, bool isSqlServer, int defaultPort, out string host, out int port, out string problem)
164:     {
165:         host = string.Empty;
166:         port = defaultPort;
167:         problem = string.Empty;
168:         var builder = new DbConnectionStringBuilder();
169:         try
170:         {
171:             builder.ConnectionString = connectionString;
172:         }
173:         catch (ArgumentException)
174:         {
175:             problem = "is not a valid connection string";
176:             return false;
177:         }
178: 
179:         if (isSqlServer)
180:         {
181:             var server = FirstValue(builder, "Server", "Data Source", "Address", "Addr", "Network Address");
182:             if (server is null)
183:             {
184:                 problem = "names no server";
185:                 return false;
186:             }
187: 
188:             if (server.StartsWith("(localdb)", StringComparison.OrdinalIgnoreCase))
189:             {
190:                 problem = "names a LocalDB server, which has no TCP endpoint on Linux";
191:                 return false;
192:             }
193: 
194:             if (server.StartsWith("tcp:", StringComparison.OrdinalIgnoreCase))
195:             {
196:                 server = server[4..];
197:             }
198: 
199:             var comma = server.IndexOf(',', StringComparison.Ordinal);
200:             if (comma >= 0)
201:             {
202:                 if (!int.TryParse(server[(comma + 1)..].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out port))
203:                 {
204:                     problem = "names a server with an unreadable port";
205:                     return false;
206:                 }
207: 
208:                 server = server[..comma];
209:             }
210: 
211:             host = server.Split('\\')[0].Trim();
212:         }
213:         else
214:         {
215:             var server = FirstValue(builder, "Host", "Server");
216:             if (server is null)
217:             {
218:                 problem = "names no host";
219:                 return false;
220:             }
221: 
222:             host = server.Split(',')[0].Trim();
223:             var portText = FirstValue(builder, "Port");
224:             if (portText is not null && !int.TryParse(portText, NumberStyles.Integer, CultureInfo.InvariantCulture, out port))
225:             {
226:                 problem = "names an unreadable port";
227:                 return false;
228:             }
229:         }
230: 
231:         if (host.Length == 0 || host == ".")
232:         {
233:             host = "localhost";
234:         }
235: 
236:         return true;
237:     }
238: 
239:     private static string? FirstValue(DbConnectionStringBuilder builder, params string[] keys)
240:     {
241:         foreach (var key in keys)
242:         {
243:             if (builder.TryGetValue(key, out var value) && value is not null && !string.IsNullOrWhiteSpace(value.ToString()))
244:             {
245:                 return value.ToString()!.Trim();
246:             }
247:         }
248: 
249:         return null;
250:     }
251: }
