253: /// <summary>
254: /// TR-MCP-NUKE-018: Real host boundary: process environment, file system, docker CLI (inspect and start only) and TCP.
255: /// </summary>
256: sealed class SystemProviderTestHost : IProviderTestHost
257: {
258:     /// <inheritdoc />
259:     public string? GetVariable(string name) => Environment.GetEnvironmentVariable(name);
260: 
261:     /// <inheritdoc />
262:     public void SetVariable(string name, string value) => Environment.SetEnvironmentVariable(name, value);
263: 
264:     /// <inheritdoc />
265:     public string? ReadFile(string path) => File.Exists(path) ? File.ReadAllText(path) : null;
266: 
267:     /// <inheritdoc />
268:     public ProviderTestContainerState GetContainerState(string containerName)
269:     {
270:         var (exitCode, output) = Docker("inspect", "--format", "{{.State.Status}}", containerName);
271:         if (exitCode != 0)
272:         {
273:             return ProviderTestContainerState.Missing;
274:         }
275: 
276:         return string.Equals(output.Trim(), "running", StringComparison.Ordinal)
277:             ? ProviderTestContainerState.Running
278:             : ProviderTestContainerState.Stopped;
279:     }
280: 
281:     /// <inheritdoc />
282:     public bool StartContainer(string containerName)
283:         => Docker("start", containerName).ExitCode == 0
284:            && GetContainerState(containerName) == ProviderTestContainerState.Running;
285: 
286:     /// <inheritdoc />
287:     public bool CanConnect(string host, int port, TimeSpan timeout)
288:     {
289:         try
290:         {
291:             using var client = new TcpClient();
292:             return client.ConnectAsync(host, port).Wait(timeout) && client.Connected;
293:         }
294:         catch (Exception exception) when (exception is SocketException or AggregateException)
295:         {
296:             return false;
297:         }
298:     }
299: 
300:     private static (int ExitCode, string Output) Docker(params string[] arguments)
301:     {
302:         var start = new ProcessStartInfo("docker") { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
303:         foreach (var argument in arguments)
304:         {
305:             start.ArgumentList.Add(argument);
306:         }
307: 
308:         using var process = Process.Start(start) ?? throw new InvalidOperationException("Could not start docker.");
309:         var output = process.StandardOutput.ReadToEndAsync();
310:         var error = process.StandardError.ReadToEndAsync();
311:         if (!process.WaitForExit(TimeSpan.FromMinutes(2)))
312:         {
313:             process.Kill(entireProcessTree: true);
314:             return (-1, string.Empty);
315:         }
316: 
317:         _ = error.GetAwaiter().GetResult();
318:         return (process.ExitCode, output.GetAwaiter().GetResult());
319:     }
320: }
